def read_number(n: int) -> str:
    if n == 0:
        return '영'

    digits = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    def read_group(num):
        """Read a group of 4 digits without the unit"""
        if num == 0:
            return ''

        result = ''

        # 천 (thousands)
        thousands = num // 1000
        if thousands > 0:
            if thousands == 1:
                result += '천'
            else:
                result += digits[thousands] + '천'

        # 백 (hundreds)
        hundreds = (num % 1000) // 100
        if hundreds > 0:
            if hundreds == 1:
                result += '백'
            else:
                result += digits[hundreds] + '백'

        # 십 (tens)
        tens = (num % 100) // 10
        if tens > 0:
            if tens == 1:
                result += '십'
            else:
                result += digits[tens] + '십'

        # 일 (ones)
        ones = num % 10
        if ones > 0:
            result += digits[ones]

        return result

    # Split into groups of 4 digits from right to left
    # Group 0: ones, Group 1: 만, Group 2: 억
    groups = []
    temp = n
    while temp > 0:
        groups.append(temp % 10000)
        temp //= 10000

    result = ''

    # Process groups from left to right (reverse order)
    for i in range(len(groups) - 1, -1, -1):
        group_val = groups[i]

        if group_val == 0:
            continue

        group_str = read_group(group_val)

        if i == 2:  # 억 group
            result += group_str + '억'
        elif i == 1:  # 만 group
            if group_val == 1:
                result += '만'
            else:
                result += group_str + '만'
        else:  # i == 0, ones group
            result += group_str

    return result

